#include <iostream>
#include <string>
using namespace std;

int main() {
    string tag;
    cin >> tag;
    string low = "";
    for (int i = 0; i < (int)tag.length(); i++) {
        char c = tag[i];
        if (c >= 'A' && c <= 'Z') {
            c = c - 'A' + 'a';
        }
        low += c;
    }
    bool ok = true;
    int n = low.length();
    for (int i = 0; i < n / 2; i++) {
        if (low[i] != low[n - 1 - i]) {
            ok = false;
        }
    }
    if (ok) {
        cout << "Palindrome" << endl;
    } else {
        cout << "Not a palindrome" << endl;
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string a, b;
    cin >> a >> b;
    int ca[26] = {0};
    int cb[26] = {0};
    for (int i = 0; i < (int)a.length(); i++) {
        char c = a[i];
        if (c >= 'A' && c <= 'Z') {
            c = c - 'A' + 'a';
        }
        ca[c - 'a']++;
    }
    for (int i = 0; i < (int)b.length(); i++) {
        char c = b[i];
        if (c >= 'A' && c <= 'Z') {
            c = c - 'A' + 'a';
        }
        cb[c - 'a']++;
    }
    bool same = true;
    for (int i = 0; i < 26; i++) {
        if (ca[i] != cb[i]) {
            same = false;
        }
    }
    if (same) {
        cout << "Anagrams" << endl;
    } else {
        cout << "Not anagrams" << endl;
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string target;
    cin >> target;
    // lowercase the target word
    for (int i = 0; i < (int)target.length(); i++) {
        char c = target[i];
        if (c >= 'A' && c <= 'Z') {
            c = c - 'A' + 'a';
        }
        target[i] = c;
    }
    cin.ignore(); // skip the newline left after reading the word
    string line;
    getline(cin, line);

    int count = 0;
    string word = "";
    for (int i = 0; i <= (int)line.length(); i++) {
        if (i == (int)line.length() || line[i] == ' ') {
            if (word.length() > 0) {
                // lowercase the scanned word, then compare
                for (int j = 0; j < (int)word.length(); j++) {
                    char c = word[j];
                    if (c >= 'A' && c <= 'Z') {
                        c = c - 'A' + 'a';
                    }
                    word[j] = c;
                }
                if (word == target) {
                    count++;
                }
                word = "";
            }
        } else {
            word += line[i];
        }
    }
    cout << "Count: " << count << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;
    string out = "";
    for (int i = 0; i < (int)s.length(); i++) {
        char c = s[i];
        int run = 1;
        for (int j = i + 1; j < (int)s.length() && s[j] == c; j++) {
            run++;
        }
        out += c;
        if (run >= 10) {
            out += (char)('0' + run / 10);
        }
        out += (char)('0' + run % 10);
        i = i + run - 1; // jump past this run (for-loop adds 1 more)
    }
    cout << "Compressed: " << out << endl;
    return 0;
}

