#include <iostream>
#include <string>
using namespace std;

int main() {
    string plate;
    cin >> plate;
    int n = plate.length();

    bool allowed = true;
    bool hasDigit = false;
    bool hasLetter = false;
    int digitSum = 0;
    for (int i = 0; i < n; i++) {
        char c = plate[i];
        bool letter = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
        bool digit = (c >= '0' && c <= '9');
        if (!letter && !digit) {
            allowed = false;
        }
        if (digit) {
            hasDigit = true;
            digitSum += c - '0';
        }
        if (letter) {
            hasLetter = true;
        }
    }

    string r1 = "FAIL", r2 = "FAIL", r3 = "FAIL", r4 = "FAIL", r5 = "FAIL";
    if (n >= 6 && n <= 10) {
        r1 = "PASS";
    }
    if (allowed) {
        r2 = "PASS";
    }
    if (hasDigit) {
        r3 = "PASS";
    }
    if (hasLetter) {
        r4 = "PASS";
    }
    if (digitSum % 7 == 0) {
        r5 = "PASS";
    }

    cout << "Rule 1 (length 6-10): " << r1 << endl;
    cout << "Rule 2 (letters and digits only): " << r2 << endl;
    cout << "Rule 3 (has a digit): " << r3 << endl;
    cout << "Rule 4 (has a letter): " << r4 << endl;
    cout << "Rule 5 (digit sum divisible by 7): " << r5 << endl;
    if (r1 == "PASS" && r2 == "PASS" && r3 == "PASS" && r4 == "PASS" && r5 == "PASS") {
        cout << "Verdict: VALID" << endl;
    } else {
        cout << "Verdict: INVALID" << endl;
    }
    return 0;
}

#include <iostream>
#include <string>
#include <iomanip>
using namespace std;

int main() {
    string line;
    getline(cin, line);

    int count = 0;
    int totalLen = 0;
    string longest = "";
    string shortest = "";
    string word = "";
    for (int i = 0; i <= (int)line.length(); i++) {
        if (i == (int)line.length() || line[i] == ' ') {
            if (word.length() > 0) {
                count++;
                totalLen += word.length();
                if (count == 1) {
                    longest = word;
                    shortest = word;
                } else {
                    if ((int)word.length() > (int)longest.length()) {
                        longest = word;
                    }
                    if ((int)word.length() < (int)shortest.length()) {
                        shortest = word;
                    }
                }
                word = "";
            }
        } else {
            word += line[i];
        }
    }

    double avg = (double)totalLen / count;
    cout << "Words: " << count << endl;
    cout << "Longest: " << longest << endl;
    cout << "Shortest: " << shortest << endl;
    cout << fixed << setprecision(2) << "Average: " << avg << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string line;
    getline(cin, line);

    // manual split: locate the two commas by scanning
    int c1 = -1, c2 = -1;
    for (int i = 0; i < (int)line.length(); i++) {
        if (line[i] == ',') {
            if (c1 == -1) {
                c1 = i;
            } else if (c2 == -1) {
                c2 = i;
            }
        }
    }
    string name = line.substr(0, c1);
    string dept = line.substr(c1 + 1, c2 - c1 - 1);
    string score = line.substr(c2 + 1);

    cout << "Name: " << name << endl;
    cout << "Department: " << dept << endl;
    cout << "Score: " << score << endl;

    // padded table row built by hand
    string paddedName = name;
    for (int i = (int)name.length(); i < 10; i++) {
        paddedName += ' ';
    }
    string paddedDept = dept;
    for (int i = (int)dept.length(); i < 12; i++) {
        paddedDept += ' ';
    }
    string paddedScore = "";
    for (int i = (int)score.length(); i < 5; i++) {
        paddedScore += ' ';
    }
    paddedScore += score;

    cout << "Row: |" << paddedName << "|" << paddedDept << "|" << paddedScore << "|" << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string word;
    int k;
    cin >> word >> k;

    string cipher = "";
    for (int i = 0; i < (int)word.length(); i++) {
        char c = word[i];
        if (c >= 'a' && c <= 'z') {
            c = (char)('a' + (c - 'a' + k) % 26);
        } else if (c >= 'A' && c <= 'Z') {
            c = (char)('A' + (c - 'A' + k) % 26);
        }
        cipher += c;
    }

    // reverse the cipher text by hand
    string back = "";
    for (int i = (int)cipher.length() - 1; i >= 0; i--) {
        back += cipher[i];
    }

    cout << "Plain: " << word << endl;
    cout << "Cipher: " << cipher << endl;
    cout << "Backwards: " << back << endl;
    return 0;
}

